                     \node[above left] at (A) {$A$};
      \node[above right] at (B) {$G$};
       \node[above left] at (C) {$I$};
        \node[above left] at (O) {$O$};
                \fill[black] (B) +(150:7.3mm) node[scale=0.8]{$33^\circ$};
                \fill[black] (C) +(30:5.5mm) node[scale=0.8]{$38^\circ$};
            \end{tikzpicture}
}
\loigiai{
Vì tam giác ${OAG}$ cân tại ${O}$ nên\\
$ \widehat{AOG} = 180^{\circ} - \widehat{OAG} - \widehat{OGA} = 180^{\circ} - 2\widehat{OGA} = 114^{\circ} $\\
Vì tam giác ${OAI}$ cân tại ${O}$ nên\\
$ \widehat{AOI} = 180^{\circ} - \widehat{OAI} - \widehat{OIA} = 180^{\circ} - 2\widehat{OIA} = 104^{\circ} $\\
Xét trong đường tròn $({O})$, ta có\\
Góc nội tiếp $\widehat{AGI}$ và góc ở tâm $\widehat{AOI}$ cùng chắn cung nhỏ $\wideparen{AI}$ nên\\
$\widehat{AGI} = \dfrac{1}{2}\widehat{AOI} = 52^{\circ}$\\
Góc nội tiếp $\widehat{AIG}$ và góc ở tâm $\widehat{AOG}$ cùng chắn cung nhỏ $\wideparen{AG}$ nên\\
$\widehat{AIG} = \dfrac{1}{2}\widehat{AOG} = 57^{\circ}$
}\end{ex}

